
/* 无自有卡片壳：作为一体化卡片的一节，与顶栏等宽相连；
   立绘与心声均通栏（与整个状态栏等宽） */
.char-page {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.header {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex-wrap: wrap;
  padding: 14px 16px 0;
}

.presence-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex: none;
}

.name {
  font-weight: 700;
  font-size: 1.35rem;
  letter-spacing: 0.01em;
}

.stage {
  color: var(--c-text-muted);
  font-size: 0.7rem;
}

.dep-label {
  margin-left: auto;
  color: var(--c-text-muted);
  font-size: 0.68rem;
}

.dep-track {
  width: 88px;
  height: 6px;
  border-radius: 3px;
  background: color-mix(in srgb, var(--card-accent, #8e8e8e) 12%, #ececef);
  overflow: hidden;
  flex: none;
}

.dep-fill {
  display: block;
  height: 100%;
  border-radius: 3px;
  transition: width 0.25s ease;
}

.dep-value {
  font-size: 0.68rem;
  color: var(--c-text-muted);
  min-width: 2ch;
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.cycle {
  padding: 2px 9px;
  border-radius: 999px;
  font-size: 0.68rem;
  font-weight: 500;
  background: var(--c-panel-inner);
  border: 1px solid var(--c-border-soft);
  color: var(--c-text-muted);
  flex: none;

  &.danger {
    background: var(--c-danger-bg);
    border-color: var(--c-danger);
    color: var(--c-danger-text);
  }
}

.voice-label {
  color: var(--c-text-faint);
  font-size: 0.72rem;
  padding: 0 16px;
}

/* 心声通栏：横贯整个状态栏宽度，顶部人物色线标识归属 */
.voice-text {
  padding: 12px 16px;
  background: color-mix(in srgb, var(--card-accent, #8e8e8e) 7%, #f7f7f8);
  border-top: 3px solid;
  color: var(--c-text);
  font-size: 0.92rem;
  line-height: 1.75;
  white-space: pre-wrap;
  word-break: break-word;
}
