
/* 卡片内的一节：同色系浅底 + 下分隔线，与下方内容等宽相连 */
.top-strip {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 18px;
  background: color-mix(in srgb, var(--card-accent, #8e8e8e) 7%, #f7f7f8);
  border-bottom: 1px solid var(--c-border-soft);
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--c-text);
  overflow: hidden;
  white-space: nowrap;
}

.cell {
  overflow: hidden;
  text-overflow: ellipsis;
}

.sep {
  width: 1px;
  height: 12px;
  background: var(--c-border);
  flex: none;
}

@media (max-width: 480px) {
  .top-strip {
    font-size: 0.82rem;
    gap: 6px;
    padding: 10px 14px;
  }
}
