
/* 与状态栏等宽；容器比例锁 1552/2072（用户立绘的原始像素比），cover 填满不变形 */
.portrait {
  position: relative;
  width: 100%;
  aspect-ratio: 1552 / 2072;
  overflow: hidden;
  background: var(--c-panel-inner);
}

.main {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  cursor: zoom-in;
}

.silhouette {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1.5px dashed var(--c-border);
  color: var(--c-text-faint);

  svg {
    width: 60px;
    height: 80px;
  }

  span {
    font-size: 0.78rem;
  }
}

.actions {
  position: absolute;
  right: 8px;
  bottom: 8px;
  display: flex;
  gap: 6px;

  button {
    padding: 4px 11px;
    border: 1px solid var(--c-border);
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.9);
    color: var(--c-text);
    font-size: 0.75rem;
    font-weight: 500;
    cursor: pointer;
    backdrop-filter: blur(6px);

    &:active {
      transform: scale(0.95);
    }
  }
}

/* 大图查看层：黑底 contain 全屏，随图比例完整显示 */
.lightbox {
  position: fixed;
  inset: 0;
  z-index: 200;
  background: rgba(0, 0, 0, 0.9);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: zoom-out;
}

.lightbox-img {
  max-width: 96vw;
  max-height: 96vh;
  object-fit: contain;
  border-radius: 4px;
}

.lightbox-hint {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 18px;
  text-align: center;
  font-size: 0.78rem;
  color: rgba(255, 255, 255, 0.55);
}
